aggiornamento AS (
  UPDATE clienti c
  SET
    nome = CASE WHEN COALESCE(c.nome, '') = '' THEN t.nome ELSE c.nome END,
    cognome = CASE WHEN COALESCE(c.cognome, '') = '' THEN t.cognome ELSE c.cognome END,
    indirizzo = CASE WHEN COALESCE(c.indirizzo, '') = '' THEN t.indirizzo ELSE c.indirizzo END,
    comune = CASE WHEN COALESCE(c.comune, '') = '' THEN t.comune ELSE c.comune END,
    partita_iva = CASE WHEN COALESCE(c.partita_iva, '') = '' THEN t.partita_iva ELSE c.partita_iva END,
    codice_fiscale = CASE WHEN COALESCE(c.codice_fiscale, '') = '' THEN t.codice_fiscale ELSE c.codice_fiscale END,
    codice_destinatario = CASE WHEN COALESCE(c.codice_destinatario, '') = '' THEN t.codice_destinatario ELSE c.codice_destinatario END,
    email = CASE WHEN COALESCE(c.email, '') = '' THEN t.email ELSE c.email END,
    pec = CASE WHEN COALESCE(c.pec, '') = '' THEN t.pec ELSE c.pec END,
    telefono = CASE WHEN COALESCE(c.telefono, '') = '' THEN t.telefono ELSE c.telefono END
  FROM t
  WHERE (NULLIF(t.partita_iva, '') IS NOT NULL AND c.partita_iva = t.partita_iva)
     OR (NULLIF(t.codice_fiscale, '') IS NOT NULL AND c.codice_fiscale = t.codice_fiscale)
     OR (LOWER(TRIM(c.denominazione)) = LOWER(TRIM(t.denominazione)))
  RETURNING c.id
)
INSERT INTO clienti (
  id, denominazione, nome, cognome, indirizzo, comune,
  partita_iva, codice_fiscale, codice_destinatario, email, pec, telefono,
  fatturato_annuo, categorie_fatturato
)
SELECT DISTINCT ON (COALESCE(NULLIF(t.partita_iva, ''), NULLIF(t.codice_fiscale, ''), LOWER(TRIM(t.denominazione))))
  'c_imp_' || substr(md5(random()::text || clock_timestamp()::text || t.denominazione), 1, 10),
  t.denominazione,
  t.nome,
  t.cognome,
  t.indirizzo,
  t.comune,
  t.partita_iva,
  t.codice_fiscale,
  t.codice_destinatario,
  t.email,
  t.pec,
  t.telefono,
  '{}'::jsonb,
  '{}'::jsonb
FROM t
WHERE NOT EXISTS (
  SELECT 1 FROM clienti c
  WHERE (NULLIF(t.partita_iva, '') IS NOT NULL AND c.partita_iva = t.partita_iva)
     OR (NULLIF(t.codice_fiscale, '') IS NOT NULL AND c.codice_fiscale = t.codice_fiscale)
     OR (LOWER(TRIM(c.denominazione)) = LOWER(TRIM(t.denominazione)))
);
